function App() {
  const [scale, setScale] = React.useState(1);
  React.useEffect(() => {
    const update = () => setScale(Math.min(1, window.innerWidth / 1440));
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, []);
  const height = 6163 * scale;
  return (
    <div className="min-h-screen bg-[#f3f0e8] text-[#20241f]">
      <div className="relative w-full overflow-x-hidden" style={{ height }}>
        <div
          className="absolute left-1/2 top-0 w-[1440px] origin-top"
          style={{ transform: `translateX(-50%) scale(${scale})` }}
        >
          <Component01NavHeroB1 />
          <Component02AboutUs />
          <Component03Products />
          <Component04WhyChooseUs />
          <Component05Testimonials />
          <Component06FooterCta />
          <Component07Footer />
        </div>
      </div>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<App />);
